  {
    "op": "add",
    "collection": "nodes",
    "id": "q-sole-chooser",
    "value": {
      "type": "question",
      "text": "Is steward the sole chooser of next work, with no exceptions (e.g., operator-approved orchestrator replacement)?",
      "status": "open",
      "meta": {
        "review_state": "current",
        "sources": [
          "source-1",
          "source-2"
        ],
        "rationale": "Raised by Blake as a live uncertainty despite the accepted claim steward-next-work; earlier exceptions (replacement-exception, atomic-replacement) were withdrawn but the question is reopened for explicit review."
      }
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "q-ask-conditions",
    "value": {
      "type": "question",
      "text": "Under what conditions should the orchestrator ask the operator (e.g., keep trying versus mark failed) rather than act autonomously?",
      "status": "open",
      "meta": {
        "review_state": "current",
        "sources": [
          "source-2"
        ],
        "rationale": "Broader than the existing 'consultation' question, which concerns only ending degraded work. Source-2 says the orchestrator 'can ask' but does not define when it should."
      }
    }
  },
  {
    "op": "add",
    "collection": "nodes",
    "id": "q-missing-cases",
    "value": {
      "type": "question",
      "text": "What important cases are missing from the theory (e.g., worker blocked by unavailable worktree, arbitrary cancellation, operator-initiated replacement, intention withdrawal)?",
      "status": "open",
      "meta": {
        "review_state": "current",
        "sources": [
          "source-2",
          "source-3"
        ],
        "rationale": "Coverage check requested by Blake. M1688/M1689 summaries and the blocked-worker observation suggest candidate gaps but are not yet analyzed."
      }
    }
  },
